/**
 * Makes the reference documents' custom click controls keyboard-operable.
 * Runs inside the sandboxed document without accessing the parent application.
 */
function initializeReferenceAccessibility() {
  document.documentElement.lang = document.documentElement.lang || "en";
  document.title = document.currentScript?.dataset.title || "My Life Reference Book";

  const style = document.createElement("style");
  style.textContent = `
    [role="button"]:focus-visible, button:focus-visible, a:focus-visible,
    input:focus-visible, textarea:focus-visible {
      outline: 3px solid #1e88e5 !important;
      outline-offset: 3px;
    }
    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after {
        animation: none !important;
        transition: none !important;
        scroll-behavior: auto !important;
      }
    }
  `;
  document.head.appendChild(style);

  document.querySelectorAll("[onclick]").forEach((control) => {
    if (control.matches("button, a, input, select, textarea")) {
      return;
    }

    control.setAttribute("role", "button");
    control.setAttribute("tabindex", "0");
    if (control.classList.contains("dot")) {
      const pillar = control.closest(".score-row")?.querySelector(".score-label")?.textContent;
      const score = control.id.split("_").pop();
      control.setAttribute("aria-label", `${pillar || "Pillar"} score ${score} out of 5`);
    }
  });

  document.addEventListener("keydown", (event) => {
    if (event.key !== "Enter" && event.key !== " ") {
      return;
    }

    const control = event.target;
    if (control instanceof HTMLElement && control.matches('[role="button"][onclick]')) {
      event.preventDefault();
      control.click();
    }
  });
}

initializeReferenceAccessibility();
